(window.__quranSurahs=window.__quranSurahs||{})[100]={"nomPhon":"Al-Aadiyaat","versets":{"1":{"text":"Par les coursiers qui halètent,","arabe":"وَٱلْعَٰدِيَٰتِ ضَبْحًۭا"},"2":{"text":"qui font jaillir des étincelles,","arabe":"فَٱلْمُورِيَٰتِ قَدْحًۭا"},"3":{"text":"qui attaquent au matin,","arabe":"فَٱلْمُغِيرَٰتِ صُبْحًۭا"},"4":{"text":"et font ainsi voler la poussière,","arabe":"فَأَثَرْنَ بِهِۦ نَقْعًۭا"},"5":{"text":"et pénètrent au centre de la troupe ennemie.","arabe":"فَوَسَطْنَ بِهِۦ جَمْعًا"},"6":{"text":"L'homme est, certes, ingrat envers son Seigneur;","arabe":"إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌۭ"},"7":{"text":"et pourtant, il est certes, témoin de cela;","arabe":"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ"},"8":{"text":"et pour l'amour des richesses il est certes ardent.","arabe":"وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ"},"9":{"text":"Ne sait-il donc pas que lorsque ce qui est dans les tombes sera bouleversé,","arabe":"۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ"},"10":{"text":"et que sera dévoilé ce qui est dans les poitrines,","arabe":"وَحُصِّلَ مَا فِى ٱلصُّدُورِ"},"11":{"text":"ce jour-là, certes, leur Seigneur sera Parfaitement Connaisseur d'eux?","arabe":"إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ"}}};